package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n, k := nextInt(), nextInt()
	champion := nextInt()
	var wins int64
	for i := int64(1); i < n; i++ {
		v := nextInt()
		if v > champion {
			champion, wins = v, 1
		} else {
			wins++
		}
		if wins >= k {
			break
		}
	}
	w.WriteString(strconv.FormatInt(champion, 10) + "\n")
}
